results = []
for sym in symbols:
    if sym not in all_tables:
        continue
    try:
        df = conn_trade.execute(f'SELECT Date, High, Low FROM "{sym}" WHERE Date >= \'2019-01-01\' AND Date <= \'2019-12-31\'').fetchdf()
        if len(df) == 0:
            continue
        df = df[df['Low'] > 0]
        cnt = ((df['High'] - df['Low']) > 0.2 * df['Low']).sum()
        results.append((sym, int(cnt)))
    except Exception as e:
        print(sym, e)

results.sort(key=lambda x: -x[1])
print(results[:15])
